function emailKey(value) {
  if (typeof value !== "string") return null;
  const email = value.trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : null;
}

function contacts(rows, provider) {
  if (!Array.isArray(rows)) throw new Error("Invalid contact list from " + provider);
  return rows.flatMap((row) => {
    if (provider === "pipedrive" && row?.is_deleted === true) return [];
    const id = row?.id;
    if ((typeof id !== "string" && typeof id !== "number") || String(id).trim() === "") {
      throw new Error("A contact returned by " + provider + " has no record ID");
    }
    if (provider === "hubspot" && (!row.properties || typeof row.properties !== "object")) {
      throw new Error("A HubSpot contact is missing the requested properties");
    }
    if (provider === "pipedrive" && row.emails != null && !Array.isArray(row.emails)) {
      throw new Error("A Pipedrive person returned an invalid email list");
    }
    const addresses =
      provider === "pipedrive"
        ? (row.emails ?? []).map((address) => address?.value)
        : [row.properties.email, ...(row.properties.hs_additional_emails ?? "").split(";")];
    const firstName = provider === "pipedrive" ? row.first_name : row.properties.firstname;
    return [
      {
        id: String(id),
        email: emailKey(addresses[0]),
        aliases: [...new Set(addresses.map(emailKey).filter(Boolean))],
        firstName: typeof firstName === "string" ? firstName.trim() : "",
      },
    ];
  });
}

function addPage(state, rows, cursor, provider) {
  const before = state ?? { rows: [], seen: [] };
  if (cursor !== null && (typeof cursor !== "string" || !cursor || before.seen.includes(cursor))) {
    throw new Error("Invalid or repeated " + provider + " contact cursor");
  }
  return {
    rows: before.rows.concat(contacts(rows, provider)),
    seen: cursor === null ? before.seen : [...before.seen, cursor],
  };
}

const pages = $input.all();
let state = null;
for (const {
  json: { body },
} of pages) {
  if (body?.success !== true)
    throw new Error("Pipedrive did not return a successful contacts page");
  state = addPage(state, body.data, body.additional_data?.next_cursor ?? null, "pipedrive");
}
if (pages.at(-1)?.json.body?.additional_data?.next_cursor != null || !state) {
  throw new Error("The Pipedrive contacts list is incomplete");
}
return [{ json: { contacts: state.rows } }];

