function addPage(state, rows, cursor, provider) {
  const before = state ?? { rows: [], seen: [] };
  if (cursor !== null && (typeof cursor !== "string" || !cursor || before.seen.includes(cursor))) {
    throw new Error("Invalid or repeated " + provider + " contact cursor");
  }
