function readHubSpotPage(body) {
  if (!Array.isArray(body?.results)) throw new Error("Invalid HubSpot contacts page");
  const next = body.paging?.next;
  if (next != null && (typeof next.after !== "string" || !next.after.trim())) {
    throw new Error("Invalid HubSpot contact cursor");
  }
  return { rows: body.results, cursor: next?.after ?? null };
}

function indexEmails(rows) {
  const identities = new Map();
  for (const row of rows) {
    for (const alias of row.aliases) {
      if (!identities.has(alias)) identities.set(alias, new Set());
      identities.get(alias).add(row.id);
    }
  }
  return identities;
}

function planCopies(pipedrive, hubspot) {
  const copies = [];
  const ambiguous = new Set();
  let missingPipedriveName = 0;
  const p = indexEmails(pipedrive);
  const h = indexEmails(hubspot);
  for (const [rows, source, target, destination] of [
    [pipedrive, p, "hubspot", h],
    [hubspot, h, "pipedrive", p],
  ]) {
    const selected = new Set();
    for (const { email, firstName, aliases } of rows) {
      if (!email || selected.has(email) || aliases.some((alias) => destination.has(alias)))
        continue;
      selected.add(email);
      if (source.get(email)?.size !== 1) {
        ambiguous.add(target + "/" + email);
        continue;
      }
      if (target === "pipedrive" && !firstName) {
        missingPipedriveName++;
        continue;
      }
      copies.push({ target, email, firstName });
    }
  }
  return {
    copies,
    totals: {
      hubspotCreated: copies.filter((item) => item.target === "hubspot").length,
      pipedriveCreated: copies.filter((item) => item.target === "pipedrive").length,
      ambiguousEmails: ambiguous.size,
      missingPipedriveName,
    },
  };
}

const pages = $input.all();
let state = null;
let cursor;
for (const {
  json: { body },
} of pages) {
  const page = readHubSpotPage(body);
  cursor = page.cursor;
  state = addPage(state, page.rows, cursor, "hubspot");
}
if (cursor !== null || !state) throw new Error("The HubSpot contacts list is incomplete");
const pipedrive = $("Collect Pipedrive contacts").first().json.contacts;
const { copies, totals } = planCopies(pipedrive, state.rows);
return (copies.length ? copies : [{ target: "done" }]).map((contact) => ({
  json: { ...contact, totals },
}));

function requestBody(item) {
  if (item.target === "pipedrive") {
    return { name: item.firstName, emails: [{ value: item.email, primary: true }] };
  }
  return {
    properties: { email: item.email, ...(item.firstName ? { firstname: item.firstName } : {}) },
  };
}

const item = $input.first();
return [{ json: { ...item.json, body: requestBody(item.json) } }];

function emailKey(value) {
  if (typeof value !== "string") return null;
  const email = value.trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : null;
}

function confirmContact(body, item) {
  const id = body?.id;
  const actualEmail =
    item.target === "pipedrive"
      ? body?.emails?.find((email) => emailKey(email?.value) === item.email)?.value
      : body?.properties?.email;
  if (
    (typeof id !== "string" && typeof id !== "number") ||
    !String(id).trim() ||
    emailKey(actualEmail) !== item.email
  ) {
    throw new Error(
      item.target +
        " contact creation was not confirmed. Check the destination CRM before rerunning.",
    );
  }
}

const saved = $input.first().json;
const contact = $("Prepare Pipedrive name and email").itemMatching(0).json;
confirmContact(saved?.success === true ? saved.data : null, contact);
return [{ json: { totals: contact.totals } }];

